function SHEET(nombreBase){ return nombreBase + "_" + CONFIG.codigoProyecto; }

// ══════════════════════════════════════════════
//  VARIOS PROYECTOS (v3.3.0)
//  Cada proyecto tiene su enlace con ?p=CODIGO (ej. index.html?p=GT01). El
//  código del enlace decide a qué proyecto se entra; el servidor (12_Proyectos.gs)
//  entrega el Excel y los datos de ese proyecto, y esta página los aplica con
//  fijarProyecto(). Con el enlace SIN ?p= se entra al proyecto predeterminado.
//  Mientras no se active el modo varios proyectos en el servidor, todo sigue
//  funcionando como siempre con un solo proyecto.
// ══════════════════════════════════════════════
var PROYECTO_PREDETERMINADO = "GT02"; // proyecto al que entra la gente con el enlace de siempre (sin ?p=)
var PROYECTO_URL = "";                // el ?p= del enlace (vacío si no trae)
try{ PROYECTO_URL=(new URLSearchParams(location.search).get("p")||"").trim(); }catch(e){}
var PROYECTO_ACTUAL = null;           // datos del proyecto en uso (después de iniciar sesión)

function proyectoEnUso(){ return PROYECTO_ACTUAL ? PROYECTO_ACTUAL.codigo : (PROYECTO_URL||PROYECTO_PREDETERMINADO); }

// Pone este proyecto como el activo en la página: su Excel, su nombre, sus módulos.
function fijarProyecto(info){
  if(!info||!info.codigo) return;
  PROYECTO_ACTUAL=info;
  if(info.sheetId){ SHEET_ID=info.sheetId; SHEETS_URL="https://sheets.googleapis.com/v4/spreadsheets/"+SHEET_ID+"/values/"; }
  CONFIG.codigoProyecto=info.codigo;
  if(info.nombre) CONFIG.nombreProyecto=info.nombre;
  if(info.ubicacion) CONFIG.ubicacion=info.ubicacion;
  if(info.empresa) CONFIG.empresa=info.empresa;
  if(info.paisLegal) CONFIG.paisLegal=info.paisLegal;
  if(info.prefijoTrabajador) CONFIG.prefijoTrabajador=info.prefijoTrabajador;
  if(info.prefijoMaquina) CONFIG.prefijoMaquina=info.prefijoMaquina;
  if(info.colorPaleta) CONFIG.colorPaletaDefecto=info.colorPaleta;
  if(info.leyenda) CONFIG.leyendaCarnet=info.leyenda;
  CONFIG.modulos=info.modulos||[];
  aplicarConfigProyecto();
  aplicarModulos(CONFIG.modulos);
}

// Módulos que SÍ usa el proyecto (columna Modulos del Excel maestro). Vacío = todos.
function aplicarModulos(lista){
  lista=lista||[];
  var mapa={horometro:"abrirHorometro",armado:"abrirArmadoPernos",epp:"abrirEPP",salud:"abrirSalud"};
  Object.keys(mapa).forEach(function(k){
    var visible=(!lista.length)||lista.indexOf(k)>=0;
    document.querySelectorAll('#menuMas .menu-item[onclick^="'+mapa[k]+'("]').forEach(function(el){ el.style.display=visible?"":"none"; });
  });
}

