// Aplica CONFIG a los textos estáticos del HTML (título de pestaña,
// pantalla de login, encabezado de la app) — así, si CONFIG cambia
// (por ejemplo, al adaptar este archivo para un GT03), no hace
// falta buscar y reemplazar texto suelto en el HTML.
function aplicarConfigProyecto(){
  document.title = CONFIG.nombreProyecto;
  var elLoginT = document.getElementById("loginTitulo");
  if(elLoginT) elLoginT.textContent = "🔒 " + CONFIG.nombreProyecto;
  var elLoginS = document.getElementById("loginSub");
  if(elLoginS) elLoginS.textContent = CONFIG.ubicacion + " · " + CONFIG.empresa;
  var elAppT = document.getElementById("appTitulo");
  if(elAppT) elAppT.textContent = "🏗 " + CONFIG.nombreProyecto;
  var elAppS = document.getElementById("appSub");
  if(elAppS) elAppS.textContent = CONFIG.ubicacion + " · " + CONFIG.empresa;
}

// ══════════════════════════════════════════════
//  CONFIG REMOTO — lee Config_GT02 (Clave|Valor) y sobreescribe el
//  objeto CONFIG local + la paleta de colores. Se llama al arrancar
//  la app (antes del login) y cada vez que Admin guarda un cambio en
//  Ajustes/Apariencia, así todos los dispositivos ven lo mismo. Si la
//  hoja todavía no existe (primera vez que se usa esta versión), se
//  crea sola con los valores que ya tenía el sistema — mismo patrón
//  que eppCargarCatalogo/saludCargarCatalogo.
// ══════════════════════════════════════════════
function cargarConfigRemota(){
  return sheetsGet(SHEET("Config")+"!A2:B").then(function(resp){
    var rows = resp.values || [];
    if(!rows.length) throw new Error("vacio");
    return rows;
  }).catch(function(){
    return gasPost("asegurarConfig",{}).then(function(){
      return sheetsGet(SHEET("Config")+"!A2:B");
    }).then(function(resp){ return resp.values || []; });
  }).then(function(rows){
    var mapa = {};
    rows.forEach(function(r){ if(r[0]) mapa[r[0].toString().trim()] = (r[1]||"").toString(); });

    if(mapa.nombreProyecto) CONFIG.nombreProyecto = mapa.nombreProyecto;
    if(mapa.ubicacion)      CONFIG.ubicacion      = mapa.ubicacion;
    if(mapa.empresa)        CONFIG.empresa        = mapa.empresa;
    if(mapa.paisLegal)      CONFIG.paisLegal      = mapa.paisLegal;
    if(mapa.leyendaCarnet)  CONFIG.leyendaCarnet  = mapa.leyendaCarnet;
    aplicarConfigProyecto();

    aplicarColores(
      mapa.colorPrimario   || "#1B4332",
      mapa.colorSecundario || "#2D6A4F",
      mapa.colorClaro      || "#D8F3DC",
      mapa.colorXclaro     || "#EBF7ED",
      mapa.colorBorde      || "#B7E4C7",
      mapa.colorPastel     || "#95D5B2"
    );
    return mapa;
  });
}

function iniciarApp(){
  aplicarConfigProyecto();
  var guardada=null;
  try{ guardada=JSON.parse(localStorage.getItem("gt02_sesion")||"null"); }catch(e){}
  // v3.1.0: una sesión guardada sin token (de versiones anteriores) o con
  // el token vencido ya no sirve — se pide iniciar sesión otra vez.
  var vigente=!!(guardada && guardada.nombre && guardada.token && guardada.exp && guardada.exp>Date.now());
  // v3.3.0: si el enlace pide OTRO proyecto distinto al de la sesión guardada, esa sesión no sirve aquí.
  if(vigente && PROYECTO_URL && guardada.proyecto && (guardada.proyecto.codigo||"").toLowerCase()!==PROYECTO_URL.toLowerCase()) vigente=false;
  if(vigente){
    SESION=guardada;
    if(guardada.proyecto) fijarProyecto(guardada.proyecto);
    cargarConfigRemota().catch(function(){}); // valores por defecto quedan si falla la carga remota
    mostrarApp();
    return;
  }
  if(guardada) localStorage.removeItem("gt02_sesion");
  cargarInfoProyectoLogin();
}

// Pantalla de login: si el enlace trae ?p=, se piden al servidor los datos de ESE proyecto
// (su Excel, su nombre) antes de leer su configuración.
function cargarInfoProyectoLogin(){
  var seguir=function(){ cargarConfigRemota().catch(function(){}); };
  if(!PROYECTO_URL){ seguir(); return; }
  gasPost("infoProyecto",{codigo:PROYECTO_URL}).then(function(r){
    if(r&&r.ok&&r.proyecto) fijarProyecto(r.proyecto);
    seguir();
  }).catch(function(e){
    var eb=document.getElementById("loginErr");
    if(eb){ eb.textContent="Este enlace no corresponde a un proyecto activo ("+PROYECTO_URL+")."; eb.style.display="block"; }
    seguir();
  });
}

function intentarLogin(){
  var usuario=document.getElementById("loginUser").value.trim();
  var pin=document.getElementById("loginPin").value.trim();
  var errBox=document.getElementById("loginErr");
  errBox.style.display="none";
  if(!usuario||!pin){
    errBox.textContent="Escribe tu usuario y tu PIN.";
    errBox.style.display="block";
    return;
  }
  gasPost("login",{usuario:usuario,pin:pin,proyecto:proyectoEnUso()}).then(function(r){
    if(r && r.ok){
      SESION={usuario:r.usuario,nombre:r.nombre,rol:r.rol||"Operador",token:r.token,exp:r.exp,global:!!r.global,proyecto:r.proyecto||null,proyectos:r.proyectos||null};
      if(r.proyecto) fijarProyecto(r.proyecto);
      localStorage.setItem("gt02_sesion",JSON.stringify(SESION));
      // Usuario global con varios proyectos que entró por el enlace de siempre (sin ?p=): elige a cuál entrar.
      if(SESION.global && SESION.proyectos && SESION.proyectos.length>1 && !PROYECTO_URL && typeof mostrarSelectorProyecto==="function"){
        mostrarSelectorProyecto(true);
        return;
      }
      mostrarApp();
    } else {
      errBox.textContent="Usuario o PIN incorrecto.";
      errBox.style.display="block";
    }
  }).catch(function(e){
    // Si el servidor respondió con un mensaje (ej. "Usuario bloqueado por
    // intentos fallidos") se muestra tal cual; solo los errores de red
    // dicen "no se pudo conectar".
    var m=(e&&e.message)||"";
    var esRed=!m||/failed to fetch|network|HTTP|load failed|conexi/i.test(m);
    errBox.textContent=esRed?"No se pudo conectar. Verifica tu conexión e intenta de nuevo.":m;
    errBox.style.display="block";
  });
}

function mostrarApp(){
  document.getElementById("loginScreen").style.display="none";
  document.getElementById("appContent").style.display="block";
  document.getElementById("sesionNombre").textContent=SESION.nombre;
  document.getElementById("verApp").textContent=APP_VERSION;
  // Menú de administración: Admin ve todo. Supervisor ve el mismo
  // menú EXCEPTO Gestión de usuarios y Gestión de máquinas (rol
  // intermedio — acceso a reportes/catálogos/ajustes, sin poder
  // tocar cuentas de acceso ni el parque de maquinaria). Operador no
  // ve nada de esto.
  var rol = (SESION.rol||"").toLowerCase();
  var isAdmin = rol==="admin";
  var isSupervisor = rol==="supervisor";
  var isLectura = (typeof esUsuarioSoloLectura==="function") && esUsuarioSoloLectura();
  var menuAdmin = document.getElementById("menuAdmin");
  if(menuAdmin) menuAdmin.style.display = (isAdmin||isSupervisor) ? "block" : "none";
  var miUsuarios = document.getElementById("miGestionUsuarios");
  if(miUsuarios) miUsuarios.style.display = isAdmin ? "block" : "none";
  var miMaquinas = document.getElementById("miGestionMaquinas");
  if(miMaquinas) miMaquinas.style.display = isAdmin ? "block" : "none";
  // v3.3.0 — varios proyectos: solo un administrador GENERAL (usuario global) gestiona accesos;
  // un usuario global con acceso a más de un proyecto puede cambiar de proyecto.
  var esGlobal = !!SESION.global;
  var miAccesos = document.getElementById("miAccesos");
  if(miAccesos) miAccesos.style.display = (esGlobal && isAdmin) ? "block" : "none";
  var miCambiar = document.getElementById("miCambiarProyecto");
  if(miCambiar) miCambiar.style.display = (esGlobal && SESION.proyectos && SESION.proyectos.length>1) ? "block" : "none";
  aplicarModulos(CONFIG.modulos);
  // Rol "Solo lectura": puede consultar historial, reportes, inventario y los
  // módulos, pero no registrar ni modificar nada (el servidor lo impide de
  // todos modos). Se esconden Préstamo y Devolución y se arranca en Historial.
  document.body.classList.toggle("rol-lectura", isLectura);
  if(!document.getElementById("estiloRolLectura")){
    var st=document.createElement("style"); st.id="estiloRolLectura";
    st.textContent=".rol-lectura .req-escritura{display:none!important}";
    document.head.appendChild(st);
  }
  if(isLectura){
    var tabsPrincipales=document.querySelector(".tabs");
    if(tabsPrincipales){
      if(tabsPrincipales.children[0]) tabsPrincipales.children[0].style.display="none";
      if(tabsPrincipales.children[1]) tabsPrincipales.children[1].style.display="none";
    }
    document.getElementById("sesionNombre").textContent=SESION.nombre+" (solo lectura)";
    goTab(2);
  }
}

function cerrarSesion(){
  localStorage.removeItem("gt02_sesion");
  location.reload();
}
